package br.com.catalogo;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;
import java.nio.file.*;
import java.net.*;
import java.net.http.*;
import java.util.*;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;

class CloudSyncTest {
 @TempDir Path temp;Biblioteca library;CloudSync sync;
 @BeforeEach void setup()throws Exception{System.setProperty("catalogo.cloud.config",temp.resolve("private").toString());System.setProperty("catalogo.cloud.api",System.getProperty("catalogo.test.cloud.api","http://127.0.0.1:1"));System.setProperty("catalogo.cloud.frontend","http://localhost:5173");library=new Biblioteca(temp.resolve("books"));sync=new CloudSync(library);}
 @AfterEach void clear(){for(String key:List.of("catalogo.cloud.config","catalogo.cloud.api","catalogo.cloud.frontend"))System.clearProperty(key);}
 @Test void staysOfflineUntilAnExplicitActionAndIsolatesProfiles()throws Exception{assertNull(sync.connection());String first=sync.deviceId();assertEquals(first,new CloudSync(library).deviceId());var other=new CloudSync(new Biblioteca(library.root,"other.sqlite"));assertNotEquals(first,other.deviceId());assertNull(other.connection());if(Files.getFileStore(Path.of(sync.config+".device")).supportsFileAttributeView("posix"))assertEquals("rw-------",java.nio.file.attribute.PosixFilePermissions.toString(Files.getPosixFilePermissions(Path.of(sync.config+".device"))));}
 @Test void fingerprintsIgnorePrivateReadingPositionAndMapOrder()throws Exception{var a=(ObjectNode)Biblioteca.JSON.readTree("{\"title\":\"Livro\",\"kind\":\"digital\",\"id\":\"one\",\"version\":1,\"metadata\":{\"author\":\"Autora\",\"page\":7,\"location\":\"pdf-scroll:7:0.5\"}}");var b=(ObjectNode)Biblioteca.JSON.readTree("{\"metadata\":{\"location\":\"pdf-scroll:99:0.1\",\"page\":99,\"author\":\"Autora\"},\"version\":12,\"id\":\"two\",\"kind\":\"digital\",\"title\":\"Livro\"}");assertEquals(CloudSync.fingerprint(a,""),CloudSync.fingerprint(b,""));b.put("title","Mudança real");assertNotEquals(CloudSync.fingerprint(a,""),CloudSync.fingerprint(b,""));}
 @Test void importsMetadataOnlyAndPreservesLocalReaderState()throws Exception{OrganizerTest.pdf(library.root.resolve("Manual.pdf"),"Manual digital");new LibraryOrganizer(library).organize((p,m)->{});var local=library.books().get(0);local.page=7;local.location="pdf-scroll:7:0.4";local.notes="Anotações locais";library.save(local);
  var remote=(ObjectNode)Biblioteca.JSON.readTree("{\"id\":\"remote-id\",\"title\":\"Novo título\",\"kind\":\"digital\",\"format\":\"PDF\",\"path\":\"/outro/computador/livro.pdf\",\"filename\":\"livro.pdf\",\"category\":\"livros_digitais/teste\",\"metadata\":{\"page\":99,\"location\":\"pdf-scroll:99:0.9\",\"notes\":\"Notas da nuvem\"},\"summary\":\"Resumo\",\"favorite\":true,\"reading\":true}");var info=new CloudSync.ConnectionInfo("http://127.0.0.1:1","device","catalog","owner@example.com","test",sync.databaseId);
  try(var c=library.connect()){sync.applyBook(c,info,local.id,remote,"",false);sync.applyBook(c,info,"cloud-only",remote,"",false);}var updated=library.books().stream().filter(b->b.id.equals(local.id)).findFirst().orElseThrow();assertEquals(local.path,updated.path);assertEquals(7,updated.page);assertEquals("pdf-scroll:7:0.4",updated.location);assertEquals("Notas da nuvem",updated.notes);var placeholder=library.books().stream().filter(b->b.id.equals("cloud-only")).findFirst().orElseThrow();assertTrue(placeholder.path.startsWith("cloud/"));assertFalse(Files.exists(library.file(placeholder)));assertEquals("true",placeholder.meta("_cloud_missing"));assertEquals(1,placeholder.page);Files.setLastModifiedTime(library.file(local),java.nio.file.attribute.FileTime.fromMillis(System.currentTimeMillis()+2000));new LibraryOrganizer(library).organize((p,m)->{});assertTrue(library.books().stream().anyMatch(b->b.id.equals("cloud-only")));assertTrue(Files.isRegularFile(library.file(local)));var reindexed=library.books().stream().filter(b->b.id.equals(local.id)).findFirst().orElseThrow();assertEquals("livros_digitais/teste",reindexed.section);assertEquals("livro.pdf",reindexed.filename);assertEquals("Novo título",reindexed.title);}
 @Test @org.junit.jupiter.api.condition.EnabledIfSystemProperty(named="catalogo.guiTest",matches="true") void cloudDialogActionsRemainInsideMinimumWindow()throws Exception{var failure=new java.util.concurrent.atomic.AtomicReference<Throwable>();javax.swing.SwingUtilities.invokeAndWait(()->{CloudDialog d=null;try{UiTheme.install();d=new CloudDialog(null,library,()->{});d.setSize(820,620);d.addNotify();d.validate();assertTrue(d.connect.isEnabled());assertFalse(d.send.isEnabled());for(var button:List.of(d.connect,d.create,d.close,d.send)){var point=javax.swing.SwingUtilities.convertPoint(button,0,0,d.getContentPane());assertTrue(point.x>=0&&point.y>=0);assertTrue(point.x+button.getWidth()<=d.getContentPane().getWidth(),button.getText());assertTrue(point.y+button.getHeight()<=d.getContentPane().getHeight(),button.getText());}}catch(Throwable e){failure.set(e);}finally{if(d!=null)d.dispose();}});if(failure.get()!=null)throw new AssertionError(failure.get());}
 JsonNode web(String method,String path,JsonNode body,int expected)throws Exception{var builder=HttpRequest.newBuilder(URI.create(System.getProperty("catalogo.test.cloud.api")+path)).header("Authorization","Bearer owner");if(body==null)builder.GET();else builder.header("Content-Type","application/json").method(method,HttpRequest.BodyPublishers.ofString(body.toString()));var response=HttpClient.newHttpClient().send(builder.build(),HttpResponse.BodyHandlers.ofString());assertEquals(expected,response.statusCode(),response.body());return Biblioteca.JSON.readTree(response.body());}
 void pair(String catalog)throws Exception{var p=sync.startPair();var approval=Biblioteca.JSON.valueToTree(Map.of("catalog_id",catalog,"user_code",p.code()));web("POST","/api/devices/pair/"+p.id()+"/approve",approval,200);assertNotNull(sync.poll(p));}
 JsonNode cloudBook(String catalog,String title)throws Exception{for(var b:web("GET","/api/catalogs/"+catalog+"/books",null,200))if(b.path("title").asText().equals(title))return b;throw new AssertionError("Book not found: "+title);}
 @Test void realJavaGoProtocolWithRetriesConflictsNotesAndRevocation()throws Exception{
  Assumptions.assumeTrue(System.getProperty("catalogo.test.cloud.api")!=null,"run through Go TestDesktopClient for real protocol coverage");
  var catalogs=web("GET","/api/catalogs",null,200);String catalog=catalogs.get(0).path("id").asText();var d=new PhysicalBooks.Draft();d.title="Livro físico Java";d.notes="Notas legadas do exemplar";String physical=PhysicalBooks.save(library,d);OrganizerTest.pdf(library.root.resolve("Manual.pdf"),"Manual digital");new LibraryOrganizer(library).organize((p,m)->{});var digital=library.books().stream().filter(b->!b.physical()).findFirst().orElseThrow();digital.page=7;digital.location="pdf-scroll:7:0.4";library.save(digital);
  pair(catalog);var info=sync.connection();assertEquals("owner@example.com",info.email());var first=sync.sync(false,m->{});assertEquals(2,first.uploaded());assertEquals(0,first.conflicts());assertEquals(2,web("GET","/api/catalogs/"+catalog+"/books",null,200).size());sync.sync(false,m->{});assertEquals(2,web("GET","/api/catalogs/"+catalog+"/books",null,200).size());
  d=new PhysicalBooks.Draft();d.title="Lote retomado";PhysicalBooks.save(library,d);var changes=sync.changes(info,false);var batch=sync.batch(info,changes,false,false);sync.pending(info,batch.toString());sync.request(info.api(),"/api/catalogs/"+catalog+"/sync",info.token(),batch);sync.sync(false,m->{});assertEquals(3,web("GET","/api/catalogs/"+catalog+"/books",null,200).size());assertNull(sync.pending(info));
  sync.addComment(physical,"Uma anotação compartilhada nova");sync.sync(false,m->{});assertTrue(sync.comments(physical).stream().anyMatch(n->n.get("body").equals("Uma anotação compartilhada nova")&&n.get("author").equals("owner")));
  var remote=(ObjectNode)cloudBook(catalog,"Livro físico Java");String cloudID=remote.path("id").asText();remote.put("title","Título editado na nuvem");web("PUT","/api/catalogs/"+catalog+"/books/"+cloudID,remote,200);sync.sync(false,m->{});var book=library.books().stream().filter(b->b.id.equals(physical)).findFirst().orElseThrow();assertEquals("Título editado na nuvem",book.title);
  var draft=BookEditor.load(library,book);draft.title="Edição local em conflito";BookEditor.save(library,book,draft);remote=(ObjectNode)cloudBook(catalog,"Título editado na nuvem");remote.put("title","Edição concorrente da nuvem");web("PUT","/api/catalogs/"+catalog+"/books/"+cloudID,remote,200);var result=sync.sync(false,m->{});assertEquals(1,result.conflicts());assertEquals("Edição local em conflito",library.books().stream().filter(b->b.id.equals(physical)).findFirst().orElseThrow().title);sync.resolve(physical,true);sync.sync(false,m->{});assertEquals("Edição local em conflito",cloudBook(catalog,"Edição local em conflito").path("title").asText());
  remote=(ObjectNode)cloudBook(catalog,"Edição local em conflito");var fields=(ObjectNode)remote.path("metadata");for(var entry:Map.ofEntries(Map.entry("author","Autora completa"),Map.entry("publisher","Editora teste"),Map.entry("year","2024"),Map.entry("edition","3"),Map.entry("language","pt"),Map.entry("pages","321"),Map.entry("keywords","teste, nuvem"),Map.entry("subject","Literatura"),Map.entry("subtitle","Subtítulo"),Map.entry("notes","Anotação revisada na web"),Map.entry("custom_field","Preservado sem perda")).entrySet())fields.put(entry.getKey(),entry.getValue());remote.put("summary","Resumo completo da nuvem");remote.put("favorite",true);remote.put("category","livros_fisicos/Literatura");web("PUT","/api/catalogs/"+catalog+"/books/"+cloudID,remote,200);sync.sync(false,m->{});var complete=library.books().stream().filter(b->b.id.equals(physical)).findFirst().orElseThrow();assertEquals("Autora completa",complete.meta("author"));assertEquals("321",complete.meta("pages"));assertEquals("Preservado sem perda",complete.meta("custom_field"));assertEquals("Anotação revisada na web",complete.notes);assertEquals("livros_fisicos/Literatura",complete.section);assertTrue(complete.favorite);assertTrue(sync.comments(physical).stream().anyMatch(n->n.get("body").equals("Anotação revisada na web")&&n.get("author").equals("owner")));sync.sync(false,m->{});assertEquals(0,sync.conflicts().size());
  remote=(ObjectNode)cloudBook(catalog,"Edição local em conflito");web("DELETE","/api/catalogs/"+catalog+"/books/"+cloudID,Biblioteca.JSON.valueToTree(Map.of("version",remote.path("version").asLong())),204);sync.sync(false,m->{});assertTrue(library.books().stream().noneMatch(b->b.id.equals(physical)));
  var cloudOnly=(ObjectNode)Biblioteca.JSON.readTree("{\"title\":\"Somente na nuvem\",\"kind\":\"digital\",\"format\":\"EPUB\",\"path\":\"/outro/computador/nao-abrir.epub\",\"filename\":\"nao-abrir.epub\",\"metadata\":{\"author\":\"Pessoa\"}}");web("POST","/api/catalogs/"+catalog+"/books",cloudOnly,201);sync.sync(false,m->{});var imported=library.books().stream().filter(b->b.title.equals("Somente na nuvem")).findFirst().orElseThrow();assertTrue(imported.path.startsWith("cloud/"));assertFalse(Files.exists(library.file(imported)));new LibraryOrganizer(library).organize((p,m)->{});assertTrue(library.books().stream().anyMatch(b->b.id.equals(imported.id)));var currentDigital=library.books().stream().filter(b->b.id.equals(digital.id)).findFirst().orElseThrow();assertEquals(7,currentDigital.page);assertEquals("pdf-scroll:7:0.4",currentDigital.location);assertTrue(Files.isRegularFile(library.file(digital)));
  try(var c=library.connect()){LibraryCategories.add(c,"livros_fisicos/Vazia");}sync.sync(false,m->{});web("DELETE","/api/catalogs/"+catalog+"/categories",Biblioteca.JSON.valueToTree(Map.of("path","livros_fisicos/Vazia")),200);sync.sync(false,m->{});assertFalse(library.categories().contains("livros_fisicos/Vazia"));sync.sync(false,m->{});assertFalse(web("GET","/api/catalogs/"+catalog+"/categories",null,200).toString().contains("/Vazia"));
  var cloudDigital=cloudBook(catalog,digital.title);var cloudImported=cloudBook(catalog,"Somente na nuvem");var relation=Biblioteca.JSON.valueToTree(Map.of("book_id",cloudDigital.path("id").asText(),"related_book_id",cloudImported.path("id").asText(),"kind","same_work"));web("POST","/api/catalogs/"+catalog+"/relations",relation,200);sync.sync(false,m->{});assertEquals(1,library.relations().size());web("DELETE","/api/catalogs/"+catalog+"/relations",relation,200);sync.sync(false,m->{});assertTrue(library.relations().isEmpty());sync.sync(false,m->{});assertTrue(web("GET","/api/catalogs/"+catalog+"/relations",null,200).isEmpty());
  sync.disconnect(false);assertNull(sync.connection());pair(catalog);assertEquals(info.deviceId(),sync.connection().deviceId());sync.sync(false,m->{});assertEquals(3,web("GET","/api/catalogs/"+catalog+"/books",null,200).size());
 }
}
